#initialize path information
regsub -all {\\} $env(SIHOME) / SIHOME
regsub -all {\\} $env(SCHOME) / SCHOME

global Graphics
set Graphics "xsup"

global toolname
global prompttoolname
set prompttoolname $toolname
set toolname sinterconnect

set si_library [file join $SIHOME TclLib]
set sc_library [file join $SCHOME TclLib]

global AdvCalDir        
set AdvCalDir [file join $si_library AdvCal]

global env
set env(si_library) $si_library

global CompatibilityDir ;
set CompatibilityDir [file join $si_library Compatibility]

if {[lsearch -exact $auto_path $si_library] == -1} {
    set auto_path "$auto_path $si_library"
}

#set the location of the graphics package
 set GraphWindow "etwish"

#source the files so that user can over-write them

#first test for tcl files in $si_library, if none
# use those in $si_library/tbc and $si_library/tcl

set fileList ""
if { [ file exists [file join $sc_library pdb.tcl] ] } {
    source [file join $sc_library pdb.tcl]
    source [file join $sc_library pdbHelpers.tcl]
    source [file join $sc_library Name.tcl]
    source [file join $sc_library write.tcl]
    source [file join $sc_library Aliases.tcl]
    source [file join $sc_library Util.tcl]
    source [file join $sc_library Mater.tcl]
    set fileList [glob [file join $sc_library *.tcl]]
} else {
    source   [file join $sc_library tbc pdb.tbc]
    source   [file join $sc_library tbc pdbHelpers.tbc]
    source   [file join $sc_library tcl Name.tcl]
    source   [file join $sc_library tcl write.tcl]
    source   [file join $sc_library tcl Aliases.tcl]
    source   [file join $sc_library tcl Util.tcl]
    source   [file join $sc_library tcl Mater.tcl]
    set fileList                   [glob  [file join $sc_library tcl *.tcl]]
    set fileList [concat $fileList [glob  [file join $sc_library tbc *.tbc]]]
}

if { [ file exists [file join $si_library Potential.tcl] ] } { ;#Potential.tcl will be encripted
    set fileList [concat $fileList [glob  [file join $si_library *.tcl]]] 
} else {
    set fileList [concat $fileList [glob  [file join $si_library tcl *.tcl]]] 
    set fileList [concat $fileList [glob  [file join $si_library tbc *.tbc]]]
}

#+-------------------------------------------------------------+
#+                      For syntax checking                    +
#+-------------------------------------------------------------+

proc CHECKON {} { }
proc CHECKOFF {} { }

#+-------------------------------------------------------------+
 #+                        Fast Mode                            +
 #+-------------------------------------------------------------+

 proc SetFastMode {} {
     # turn off time consuming modules to get structure quickly

     set msg0 " SetFastMode:\n PDE solve and mechanics solve turned off to simulate geometry"
     printWarning $msg0 

     pdbSet Compute SkipPDESolve 1 ;# turns off PDEs
     pdbSet Compute FastMode 1; #Don't create doped deposited regions or do mechanics
 }

#+-------------------------------------------------------------+
#|                     UserExit proc                           |
#+-------------------------------------------------------------+

proc UserExit { } {
     # User can override to save final structure upon panic
}


#initialize parameter handling
global pdbPath
set pdbPath $SCHOME

#+-------------------------------------------------------------+
#|                        Materials                            |
#+-------------------------------------------------------------+
addSentaurusMaterials  ;#In the core directory

# olga: file source
foreach item $fileList { source $item }

#set prompts
proc mainpr {} {
    #global toolname
    #puts -nonewline "$toolname> "
    global prompttoolname
    puts -nonewline  "$prompttoolname> "
}
proc minorpr {} {
    puts -nonewline "> "
}
set tcl_prompt1 mainpr
set tcl_prompt2 minorpr	
if { $prompttoolname != "rcx" && $prompttoolname != "rcfx" } {
    # mgoals default on
    mgoals on
}
#+-------------------------------------------------------------+
#|                        Math Params                          |
#+-------------------------------------------------------------+

# limit to 64 bit on linux
math limit.precision
#Math parameters
math compute dim=1 pardiso scale
math compute dim=2 ils     scale
math compute dim=3 ils     scale

math flow dim=2 ils !scale

math taulim = 2.0

pdbSet Math compute 1D ILS.refine.residual 3
pdbSet Math compute 2D ILS.refine.residual 2
pdbSet Math compute 3D ILS.refine.residual 2

pdbSet Math compute 1D ILS.ilut.tau       2.e-5
pdbSet Math compute 2D ILS.ilut.tau       5.e-5

pdbSet Math compute 3D ILS.ilut.tau       0.2e-3
pdbSet Math compute 3D ILS.gmres.restart  100

pdbSet Math Flow 3D ILS.ilut.tau 1.0e-4
pdbSet Math Flow 3D ILS.maxit    500

#+-------------------------------------------------------------+
#|                        Bulk Materials                       |
#+-------------------------------------------------------------+

set __bulkMaterialList {
    "AlGaN"
    "AlN"
    "Aluminum"
    "Cobalt"
    "CobaltSilicide"
    "Copper"
    "GaN"
    "Gold"
    "Insulator"
    "Metal"
    "Nickel"
    "NickelSilicide"
    "Nitride"
    "Oxide"
    "Oxynitride"
    "Platinum"
    "PlatinumSilicide"
    "PolySilicon"
    "Silicide"
    "Silicon"
    "SiliconCarbide"
    "Solder"
    "Tantalum"
    "TiNitride"
    "TiSilicide"
    "Titanium"
    "Tungsten"
    "TungstenSilicide"
} 

set __allInterfaceMaterials [ getAllInterfaceMaterials  $__bulkMaterialList ]

#+-------------------------------------------------------------+
#|                     Solution Mode                           |
#+-------------------------------------------------------------+
mode ;# clears all
pdbSet Compute minT 0.0

#+-------------------------------------------------------------+
#|                     Mechanics                               |
#+-------------------------------------------------------------+
pdbSetBoolean Mechanics UseTemperatureField 1
pdbSet        Math flow 3D ILS.refine.sts 2
#+-------------------------------------------------------------+
#|                     Potential                               |
#+-------------------------------------------------------------+

# Create initial settings for Potential
solution add name = Potential solve negative unit=V InitStep linear

foreach bulkMat $__bulkMaterialList {
    pdbSetString $bulkMat Potential InitProc         PotentialInitProc
    pdbSetString $bulkMat Potential InitSolve        PotentialInitProc
    pdbSetString $bulkMat Potential EquationProc     PotentialEquation
    pdbSetString $bulkMat Potential EquationInitProc PotentialEquationInit

    if { ![pdbIsAvailable $bulkMat Potential Abs.Error] } {
	pdbSetDouble $bulkMat Potential Abs.Error  2.59e-4
    }
    if { ![pdbIsAvailable $bulkMat Potential Rel.Error] } {
    	pdbSetDouble $bulkMat Potential Rel.Error 1e-3
    }
}

foreach intMat $__allInterfaceMaterials {
    pdbSetString $intMat Potential InitProc         InterfaceInit
    pdbSetString $intMat Potential InitSolve        InterfaceInit
    pdbSetString $intMat Potential EquationProc     InterfaceSetUp
    pdbSetString $intMat Potential EquationInitProc InterfaceSetUpInit
    if { ![pdbIsAvailable $intMat Potential Abs.Error] } {
	pdbSetDouble $intMat Potential Abs.Error 2.59e-6
    }
    if { ![pdbIsAvailable $intMat Potential Rel.Error] } {
	pdbSetDouble $intMat Potential Rel.Error 1e-3
    }
}

#+-------------------------------------------------------------+
#|                     Temperature                             |
#+-------------------------------------------------------------+

# Create initial settings for Temperature
solution add name = Temperature solve !negative unit=K InitStep linear

foreach bulkMat $__bulkMaterialList {
    pdbSetString $bulkMat Temperature InitProc          ThermalInitProc
    pdbSetString $bulkMat Temperature InitSolve         ThermalInitProc
    pdbSetString $bulkMat Temperature EquationProc      ThermalEquation
    pdbSetString $bulkMat Temperature EquationInitProc  ThermalEquationInit

    if { ![pdbIsAvailable $bulkMat Temperature Abs.Error] } {
	pdbSetDouble $bulkMat Temperature Abs.Error 0.3
    }
    if { ![pdbIsAvailable $bulkMat Temperature Rel.Error] } {
    	pdbSetDouble $bulkMat Temperature Rel.Error 1e-3
    }
}
#include Gas_Material interfaces for heat emission
set __allInterfaces "$__allInterfaceMaterials [getAllGasInterfaceMaterials $__bulkMaterialList]"
foreach intMat $__allInterfaces {
    pdbSetString $intMat Temperature InitProc         InterfaceInit
    pdbSetString $intMat Temperature InitSolve        InterfaceInit
    pdbSetString $intMat Temperature EquationProc     InterfaceSetUp
    pdbSetString $intMat Temperature EquationInitProc InterfaceSetUpInit

    if { ![pdbIsAvailable $intMat Temperature Abs.Error] } {
	pdbSetDouble $intMat Temperature Abs.Error 0.3e-2
    }
    if { ![pdbIsAvailable $intMat Temperature Rel.Error] } {
        pdbSetDouble $intMat Temperature Rel.Error 1e-3
    }
}

