    }
    if { ![pdbIsAvailable $intMat IVoidPhase Abs.Error] } {
        pdbSetDouble $intMat IVoidPhase Abs.Error 1.0e-4
    }
    if { ![pdbIsAvailable $intMat IVoidPhase Rel.Error] } {
        pdbSetDouble $intMat IVoidPhase Rel.Error 1.0e-3
    }
}

